-- Enable Row Level Security on all tables
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

-- R9: Service role bypasses RLS for internal operations
grant all on public.teams to service_role;
grant all on public.team_members to service_role;
grant all on public.documents to service_role;

-- R8: Anonymous users cannot see or change anything
revoke all on public.teams from anon;
revoke all on public.team_members from anon;
revoke all on public.documents from anon;

-- R1, R2, R3, R4, R5, R6: Custom policies based on team membership and roles
-- Helper function to check if user is a member of a team with a specific role
create function public.is_member_of_team(p_team_id bigint, p_role text)
returns boolean
language sql
security definer
stable
as $$
  select exists (
    select 1 from public.team_members
    where team_id = p_team_id
    and user_id = auth.uid()
    and role = p_role
  );
$$;

-- R1: Users can see the teams they belong to (either as viewer or editor)
create policy "Users can view teams they belong to"
on public.teams
for select
using (
  exists (
    select 1 from public.team_members
    where team_id = public.teams.id
    and user_id = auth.uid()
  )
);

-- R7: Teams and memberships cannot be created, changed or removed by users of the app
create policy "Prevent users from creating teams"
on public.teams
for insert
with check (false);

create policy "Prevent users from updating teams"
on public.teams
for update
with check (false);

create policy "Prevent users from deleting teams"
on public.teams
for delete
using (false);

create policy "Prevent users from creating team_memberships"
on public.team_members
for insert
with check (false);

create policy "Prevent users from updating team_memberships"
on public.team_members
for update
with check (false);

create policy "Prevent users from deleting team_memberships"
on public.team_members
for delete
using (false);

-- R3: Members of a team can read the team's documents (non-deleted), excluding deleted docs for everyone
create policy "Users can read team documents they have access to"
on public.documents
for select
using (
  (
    -- Check if user is a member of the document's team (any role)
    exists (
      select 1 from public.team_members
      where team_id = public.documents.team_id
      and user_id = auth.uid()
    )
    -- AND document is not deleted (R3: deleted documents hidden from every user)
    and public.documents.deleted_at is null
  )
);

-- R4: Editors can create documents in their teams; Viewers cannot
create policy "Editors can create documents in their teams"
on public.documents
for insert
with check (
  -- User must be an editor in the team
  public.is_member_of_team(public.documents.team_id, 'editor')
);

-- R5: Editors can edit any document in their teams (update policy)
-- Condition: User must be an editor in the document's team
-- Note: R5 says "After an edit, the document must still belong to a team where the user is an editor."
-- This implies the check happens on the new state (after update), which is standard for UPDATE policies.
create policy "Editors can update documents in their teams"
on public.documents
for update
using (
  public.is_member_of_team(public.documents.team_id, 'editor')
);

-- R6: Only the person who created a document can delete it
-- Condition: User must be an editor in the team (to have permission to delete)
-- AND User must be the creator of the document
create policy "Only creators can delete their documents"
on public.documents
for delete
using (
  public.is_member_of_team(public.documents.team_id, 'editor')
  and public.documents.created_by = auth.uid()
);
```

