```sql
-- Enable RLS
alter table public.accounts enable row level security;
alter table public.files enable row level security;
alter table public.file_shares enable row level security;

-- Helper function to check if user is suspended
create or replace function public.check_suspended()
returns boolean as $$
begin
  return not exists (
    select 1 from public.accounts a
    where a.user_id = auth.uid() and a.suspended = true
  );
end;
$$ language plpgsql security definer;

-- R6: Users can read their own account row. Nobody can change accounts through the app.
create policy "Users can read own account" on public.accounts for select
  using (user_id = auth.uid());

create policy "No changes to accounts" on public.accounts for all
  using (false);

-- R7: Anonymous visitors cannot see or change anything. (Implicitly handled by denying anon unless specific policy allows)
-- Explicit deny for anon on all tables just to be safe and clear intent, though create policy usually defaults to deny if not specified.
-- We will rely on specific allow policies below.

-- R8: Service role keeps full access. (Implicitly handled by service_role role bypassing RLS, but good to ensure policies don't interfere if service_role is used via functions)
-- Since service_role bypasses RLS, no specific policy needed for service role.

-- R5: Suspended accounts lose all access to files and shares, including their own files.
-- Apply to files
create policy "Suspended users cannot access files" on public.files for all
  using (check_suspended());

-- Apply to file_shares
create policy "Suspended users cannot access file_shares" on public.file_shares for all
  using (check_suspended());

-- R1: Owners can create files as themselves and can read, rename and delete their own files. A file's owner can never be changed through the app.
-- Create
create policy "Owners can create files" on public.files for insert
  with check (owner_id = auth.uid() and check_suspended());

-- Select
create policy "Owners can read files" on public.files for select
  using (owner_id = auth.uid() and check_suspended());

-- Update (rename) - owner can update name, but not owner_id (enforced by with check)
create policy "Owners can update files" on public.files for update
  using (owner_id = auth.uid() and check_suspended())
  with check (owner_id = auth.uid());

-- Delete
create policy "Owners can delete files" on public.files for delete
  using (owner_id = auth.uid() and check_suspended());

-- R2: A user can read a file shared with them while the share has not expired. If the share allows editing, they can also rename the file.
-- Select
create policy "Users can read shared files" on public.files for select
  using (
    owner_id = auth.uid() 
    or exists (
      select 1 from public.file_shares fs 
      where fs.file_id = public.files.id 
      and fs.shared_with = auth.uid()
      and (fs.expires_at is null or fs.expires_at > now())
    )
    and check_suspended()
  );

-- Update (rename)
create policy "Users can rename shared files if allowed" on public.files for update
  using (
    owner_id = auth.uid()
    or (
      exists (
        select 1 from public.file_shares fs 
        where fs.file_id = public.files.id 
        and fs.shared_with = auth.uid()
        and fs.can_edit = true
        and (fs.expires_at is null or fs.expires_at > now())
      )
      and check_suspended()
    )
  )
  with check (
    owner_id = auth.uid()
    or (
      exists (
        select 1 from public.file_shares fs 
        where fs.file_id = public.files.id 
        and fs.shared_with = auth.uid()
        and fs.can_edit = true
        and (fs.expires_at is null or fs.expires_at > now())
      )
    )
  );

-- R3: Users a file is shared with can never delete it.
create policy "Shared users cannot delete files" on public.files for delete
  using (false);

-- R4: Owners can see, create, change and remove the shares of their own files. 
-- Users can see the shares addressed to them, but not shares addressed to anyone else.
-- Note: We need to ensure users can't insert shares for other files or for other users.

-- Insert (Create share)
create policy "Owners can create shares for their files" on public.file_shares for insert
  with check (
    exists (
      select 1 from public.files f 
      where f.id = public.file_shares.file_id 
      and f.owner_id = auth.uid()
    )
    and check_suspended()
  );

-- Delete (Remove share)
create policy "Owners can delete shares of their files" on public.file_shares for delete
  using (
    exists (
      select 1 from public.files f 
      where f.id = public.file_shares.file_id 
      and f.owner_id = auth.uid()
    )
    and check_suspended()
  );

-- Update (Change share - e.g., revoke edit, extend expiry)
create policy "Owners can update shares of their files" on public.file_shares for update
  using (
    exists (
      select 1 from public.files f 
      where f.id = public.file_shares.file_id 
      and f.owner_id = auth.uid()
    )
    and check_suspended()
  )
  with check (
    exists (
      select 1 from public.files f 
      where f.id = public.file_shares.file_id 
      and f.owner_id = auth.uid()
    )
  );

-- Select (View shares)
create policy "Users can see shares addressed to them or owned by them" on public.file_shares for select
  using (
    (
      exists (
        select 1 from public.files f 
        where f.id = public.file_shares.file_id 
        and f.owner_id = auth.uid()
      )
    )
    or (
      shared_with = auth.uid()
    )
    and check_suspended()
  );

-- R3 Re-enforced for shares: Users addressed in a share cannot delete that share if it's not their own? 
-- Actually, R4 says "Users can see the shares addressed to them". It doesn't explicitly say they can delete shares addressed to them.
-- Usually, only the owner of the file manages shares. R4 says "Owners can ... remove the shares of their own files".
-- So users addressed to them cannot delete shares (even if addressed to them).
create policy "Non-owners cannot delete shares" on public.file_shares for delete
  using (false);
```

