```sql
-- Enable RLS on all tables
alter table public.restaurants enable row level security;
alter table public.restaurant_staff enable row level security;
alter table public.reservations enable row level security;

-- Create helper function to check if user is staff at a restaurant
create or replace function public.is_staff_at_restaurant(
  p_restaurant_id bigint,
  p_user_id uuid
) returns boolean stable
language sql
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.restaurant_staff
    where restaurant_staff.restaurant_id = p_restaurant_id
    and restaurant_staff.user_id = p_user_id
  );
$$;

-- Policy R5: Restaurants and staff lists cannot be changed through the app
-- Only service role can modify restaurants and restaurant_staff
create policy "restaurants_select_all" on public.restaurants
  for select using (true);

create policy "restaurants_insert_service" on public.restaurants
  for insert with check (auth.jwt() ->> 'role' = 'service_role');

create policy "restaurants_update_service" on public.restaurants
  for update using (auth.jwt() ->> 'role' = 'service_role');

create policy "restaurants_delete_none" on public.restaurants
  for delete using (false);

create policy "restaurant_staff_select_staff" on public.restaurant_staff
  for select using (auth.jwt() ->> 'role' = 'service_role');

create policy "restaurant_staff_insert_service" on public.restaurant_staff
  for insert with check (auth.jwt() ->> 'role' = 'service_role');

create policy "restaurant_staff_update_service" on public.restaurant_staff
  for update using (auth.jwt() ->> 'role' = 'service_role');

create policy "restaurant_staff_delete_none" on public.restaurant_staff
  for delete using (false);

-- Policy R7: Service role keeps full access to reservations
create policy "reservations_all_service" on public.reservations
  for all using (auth.jwt() ->> 'role' = 'service_role');

-- Policy R6: Anonymous visitors cannot see or change anything
-- Implicitly handled by requiring authentication for all other policies,
-- but we can explicitly deny if needed. Since we have specific allow policies below,
-- we just ensure no default allow exists. Supabase defaults to deny.
-- We will create specific allow policies for authenticated users.

-- Policy R1: Signed-in users can see the list of restaurants
create policy "restaurants_select_auth" on public.restaurants
  for select using (auth.role() = 'authenticated');

-- Policy R1: Guests can see their own reservations
create policy "reservations_select_guest" on public.reservations
  for select
  using (
    auth.role() = 'authenticated'
    and (
      user_id = auth.uid()
    )
  );

-- Policy R1: Restaurant staff can see every reservation at their restaurant
create policy "reservations_select_staff" on public.reservations
  for select
  using (
    auth.role() = 'authenticated'
    and is_staff_at_restaurant(restaurant_id, auth.uid())
  );

-- Policy R2: Guests can book, as themselves, only for a time in the future
create policy "reservations_insert_guest" on public.reservations
  for insert
  with check (
    auth.role() = 'authenticated'
    and user_id = auth.uid()
    and reserved_for > now()
    and status = 'booked'
  );

-- Policy R3: Guests can cancel their own `booked` reservations while the reservation time is still in the future
create policy "reservations_update_guest_cancel" on public.reservations
  for update
  using (
    auth.role() = 'authenticated'
    and user_id = auth.uid()
    and status = 'booked'
    and reserved_for > now()
  )
  with check (
    auth.role() = 'authenticated'
    and user_id = auth.uid()
    and status = 'booked'
    and reserved_for > now()
  );

-- Policy R4: Staff can mark `booked` reservations at their restaurant as `seated` or `no_show`, but only once the reservation time has passed
create policy "reservations_update_staff" on public.reservations
  for update
  using (
    auth.role() = 'authenticated'
    and is_staff_at_restaurant(restaurant_id, auth.uid())
    and status = 'booked'
    and reserved_for <= now()
  )
  with check (
    auth.role() = 'authenticated'
    and is_staff_at_restaurant(restaurant_id, auth.uid())
    and status in ('booked', 'seated', 'no_show')
    and reserved_for <= now()
  );

-- Policy R5: Reservations are never deleted
create policy "reservations_delete_none" on public.reservations
  for delete using (false);

-- Grant necessary permissions for the functions to work
grant execute on function public.is_staff_at_restaurant to authenticated, service_role;
```

