-- Enable Row Level Security on all tables
alter table public.pharmacists enable row level security;
alter table public.prescriptions enable row level security;
alter table public.dispenses enable row level security;

-- ==========================================
-- 1. Helper Functions & Triggers
-- ==========================================

-- Function to handle the dispense logic with business rules
create or replace function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_prescription record;
  v_pharmacist_id uuid;
  v_refills_left integer;
begin
  -- Fetch prescription details
  select p.*, u.id into v_prescription
  from public.prescriptions p
  join auth.users u on u.id = p.patient_id
  where p.id = p_prescription_id;

  -- Check if prescription exists
  if not found then
    raise exception 'Prescription not found';
  end if;

  -- Get current user (pharmacist)
  v_pharmacist_id := auth.uid();

  -- Rule 4: Check if caller is a pharmacist
  if not exists (select 1 from public.pharmacists where user_id = v_pharmacist_id) then
    raise exception 'Caller must be a pharmacist';
  end if;

  -- Rule 4: Check if prescription is the caller's own
  if v_prescription.patient_id = v_pharmacist_id then
    raise exception 'Pharmacists cannot dispense their own prescriptions';
  end if;

  -- Rule 4: Check if prescription has expired
  if v_prescription.expires_at < now() then
    raise exception 'Prescription has expired';
  end if;

  -- Rule 4: Check if refills left > 0
  if v_prescription.refills_left <= 0 then
    raise exception 'No refills left';
  end if;

  -- Decrement refills
  update public.prescriptions
  set refills_left = refills_left - 1
  where id = p_prescription_id;

  -- Record dispense
  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, v_pharmacist_id, now());

  -- Return updated refills left
  return (select refills_left from public.prescriptions where id = p_prescription_id);
end;
$$;

-- Trigger to auto-fire dispense function? 
-- Note: The requirement says "Implement it as public.rpc", implying a manual call, 
-- but R2 says "Nobody can create, change or delete ... directly through the app".
-- Since the function itself enforces R4 and modifies data, we don't need a trigger 
-- to call it automatically (which would bypass user control flow), but we ensure 
-- the function is the only way to modify data for dispenses.
-- However, to strictly follow "Nobody can ... directly", we rely on RLS + Security Definer.
-- No trigger is needed for logic enforcement if the RPC is called manually.

-- ==========================================
-- 2. Row Level Security Policies
-- ==========================================

-- PHARMACISTS TABLE
-- R1: Signed-in users can see who the pharmacists are.
-- R5: Anonymous cannot see.
create policy "Allow authenticated users to view pharmacists"
on public.pharmacists
for select
using (auth.role() = 'authenticated');

-- Grant service role full access (R6)
grant all on public.pharmacists to service_role;

-- PRESCRIPTIONS TABLE
-- R1: Signed-in users can see their own prescriptions.
-- R1: Patients can see their own prescriptions.
-- R1: Pharmacists can see every prescription.
-- R5: Anonymous cannot see.
create policy "Patients see own prescriptions"
on public.prescriptions
for select
using (auth.uid() = patient_id);

create policy "Pharmacists see all prescriptions"
on public.prescriptions
for select
using (exists (
  select 1 from public.pharmacists 
  where public.pharmacists.user_id = auth.uid()
));

-- R6: Service role full access
grant all on public.prescriptions to service_role;

-- R2: Nobody can create, change, delete via app.
-- We rely on the fact that standard inserts/updates/selects by anon/authenticated 
-- are blocked by the policies above (only select allowed for specific users).
-- To be explicit about blocking writes for non-service roles:
revoke insert on public.prescriptions from authenticated;
revoke update on public.prescriptions from authenticated;
revoke delete on public.prescriptions from authenticated;

-- DISPENSES TABLE
-- R1: Patients can see their own dispenses.
-- R1: Pharmacists can see every dispense.
-- R5: Anonymous cannot see.
create policy "Patients see own dispenses"
on public.dispenses
for select
using (auth.uid() = (
  select patient_id from public.prescriptions 
  where public.prescriptions.id = dispenses.prescription_id
));

create policy "Pharmacists see all dispenses"
on public.dispenses
for select
using (exists (
  select 1 from public.pharmacists 
  where public.pharmacists.user_id = auth.uid()
));

-- R6: Service role full access
grant all on public.dispenses to service_role;

-- R2: Block direct inserts/updates/deletes by authenticated users
revoke insert on public.dispenses from authenticated;
revoke update on public.dispenses from authenticated;
revoke delete on public.dispenses from authenticated;

-- ==========================================
-- 3. Anonymous User Restrictions (R5)
-- ==========================================
-- Explicitly ensure anonymous users cannot do anything.
-- The policies above use 'using' clauses that evaluate to false for anonymous users
-- (since auth.uid() != any_user_id and exists pharmacist check fails for anon).
-- However, to be safe against default 'allow' behaviors if any:
