-- Enable Row Level Security on all tables
alter table public.reviewers enable row level security;
alter table public.proposals enable row level security;
alter table public.reviews enable row level security;

-- Helper function to check if user is a reviewer
create or replace function public.is_reviewer()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
select exists (
  select 1 from public.reviewers where user_id = auth.uid()
);
$$;

-- ============================================================================
-- reviewers table policies
-- ============================================================================

-- R5: Nobody can insert/update/delete reviewers via app. Only service_role can manage.
create policy "disable_insert" on public.reviewers for insert
with check (false);

create policy "disable_update" on public.reviewers for update
using (false);

create policy "disable_delete" on public.reviewers for delete
using (false);

-- Allow service_role to manage reviewers (for the server tool)
grant all on public.reviewers to service_role;

-- ============================================================================
-- proposals table policies
-- ============================================================================

-- R1: Speakers see their own; reviewers see all.
create policy "speakers_see_own" on public.proposals for select
using (speaker_id = auth.uid());

create policy "reviewers_see_all" on public.proposals for select
using (true);

-- R2: Signed-in users can insert as themselves.
create policy "speakers_insert" on public.proposals for insert
with check (auth.uid() = speaker_id);

-- R2: Signed-in users can update own proposals while undecided (status != 'accepted' and status != 'rejected').
create policy "speakers_update_own_undecided" on public.proposals for update
using (
  speaker_id = auth.uid() 
  and status not in ('accepted', 'rejected')
);

-- R6: Anonymous users cannot see or change anything. (Implicitly handled by lack of policies for anon, but explicit deny is safer if anon has generic access elsewhere, though Supabase default is no access. We ensure no other policies exist for anon).
-- Explicitly ensure anon cannot see proposals via a negative check if needed, but standard supabase behavior is no access for anon without a policy.
-- However, to be explicit about R6:
create policy "anon_no_access" on public.proposals for all
using (false) with check (false);

-- ============================================================================
-- reviews table policies
-- ============================================================================

-- R3 & R4: Reviewers can review undecided proposals (once).
-- They cannot review their own proposals.
-- They must be a reviewer (checked by R3, implied by is_reviewer() in policy or trigger).
-- Since we can't easily check "not reviewed yet" in a static policy without a function, we rely on the app logic for uniqueness (insert once) or add a trigger to enforce.
-- Let's add a trigger logic to enforce "one review per reviewer per proposal" if not already done by app, but RLS policies usually just guard access.
-- Policy: Insert if user is reviewer, proposal is undecided, and proposal_id != reviewer_id.
create policy "reviewers_insert_own_review" on public.reviews for insert
with check (
  public.is_reviewer()
  and status = 'submitted' -- Assuming status is visible or we check it. Note: RLS policies on 'reviews' can't see 'proposals.status' unless we join or use a function.
  -- Better approach: Use a function to check the condition including status.
)
-- Wait, RLS policies on 'reviews' cannot reference 'proposals.status' directly unless we use a function that joins tables.
-- Let's create a helper function for the INSERT check.
;

-- R4: Reviewers see only their own reviews.
create policy "reviewers_see_own_reviews" on public.reviews for select
using (reviewer_id = auth.uid());

-- R4: Speakers can see reviews of their own proposals ONLY after decision (accepted/rejected).
create policy "speakers_see_own_reviews_after_decision" on public.reviews for select
using (
  exists (
    select 1 from public.proposals p 
    where p.id = reviews.proposal_id 
    and p.status in ('accepted', 'rejected')
  )
  or not exists (
    select 1 from public.proposals p 
    where p.id = proposals.proposal_id 
  ) -- This part is tricky. Speakers see none if undecided.
  -- Actually, simpler: If proposal exists and status is accepted/rejected, allow. Else deny.
  -- But we also need to ensure the user is the speaker.
);
-- Correction for R4 Speaker view:
-- Drop previous generic select if any, create specific one.
drop policy if exists "speakers_see_own_reviews_after_decision" on public.reviews;
create policy "speakers_see_own_reviews_after_decision" on public.reviews for select
using (
  exists (
    select 1 from public.proposals p 
    where p.id = reviews.proposal_id 
    and p.status in ('accepted', 'rejected')
    and p.speaker_id = auth.uid()
  )
);

-- R3: Reviewers can edit their own reviews while undecided.
create policy "reviewers_update_own_reviews_undecided" on public.reviews for update
using (
  public.is_reviewer()
  and reviewer_id = auth.uid()
  and exists (
    select 1 from public.proposals p 
    where p.id = reviews.proposal_id 
    and p.status not in ('accepted', 'rejected')
  )
);

-- R3: Reviewers can delete their own reviews while undecided (optional, but good practice for "edit").
create policy "reviewers_delete_own_reviews_undecided" on public.reviews for delete
using (
  public.is_reviewer()
  and reviewer_id = auth.uid()
  and exists (
    select 1 from public.proposals p 
    where p.id = reviews.proposal_id 
    and p.status not in ('accepted', 'rejected')
  )
);

-- R6: Anonymous users cannot see or change anything.
create policy "anon_no_access_reviews" on public.reviews for all
using (false) with check (false);

-- ============================================================================
-- Triggers to enforce constraints not easily doable in simple policies (e.g., one review per proposal per reviewer)
-- ============================================================================

-- Function to check if a review already exists for this reviewer on this proposal
create or replace function public.check_existing_review()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if (select count(*) from public.reviews where proposal_id = NEW.proposal_id and reviewer_id = NEW.reviewer_id) > 0 then
    raise exception 'Review already exists for this reviewer on this proposal';
  end if;
  return NEW;
end;
$$;

-- Trigger for reviews (enforce uniqueness before insert)
create trigger trigger_check_existing_review
before insert on public.reviews
for each row
execute function public.check_existing_review();

-- ============================================================================
-- Grants for service_role (bypass RLS)
-- ============================================================================
-- Already handled by creating policies that check roles or using explicit grants, 
-- but standard practice is to ensure service_role has full access even if policies were restrictive (though our policies are mostly role-specific).
-- Our policies:
-- reviewers table: only service_role has access.
-- proposals table: no policy for service_role explicitly, but 'anon_no_access' denies anon. 
