using (false);

-- Allow service_role to manage reviewers (for the server tool)
grant all on public.reviewers to service_role;

-- ============================================================================
-- proposals table policies
-- ============================================================================

-- R1: Speakers see their own; reviewers see all.
create policy "speakers_see_own" on public.proposals for select
using (speaker_id = auth.uid());

create policy "reviewers_see_all" on public.proposals for select
using (true);

-- R2: Signed-in users can insert as themselves.
create policy "speakers_insert" on public.proposals for insert
with check (auth.uid() = speaker_id);

-- R2: Signed-in users can update own proposals while undecided (status != 'accepted' and status != 'rejected').
create policy "speakers_update_own_undecided" on public.proposals for update
using (
  speaker_id = auth.uid() 
  and status not in ('accepted', 'rejected')
);

-- R6: Anonymous users cannot see or change anything. (Implicitly handled by lack of policies for anon, but explicit deny is safer if anon has generic permissions elsewhere, though Supabase default is no access. We ensure no other policies exist for anon).
-- Explicitly ensure anon has no access to proposals
revoke all on public.proposals from anon;
revoke all on public.proposals on all tables in schema public from anon;

-- Allow service_role full access
grant all on public.proposals to service_role;

-- ============================================================================
-- reviews table policies
-- ============================================================================

-- R3: Reviewers can insert a review if:
--   1. They are a reviewer
--   2. Proposal is undecided (not accepted/rejected)
--   3. They are reviewing their own (default auth.uid())
--   4. They are NOT reviewing their own proposal (reviewer_id != user's id in reviewers table? No, R3 says "never their own proposals". This implies if a user is both a speaker and a reviewer, they can't review their own proposal).
--   Wait, R3 says "never their own proposals". The `reviews` table has `reviewer_id`. The `proposals` table has `speaker_id`.
--   Condition: reviewer_id (from auth) != speaker_id (from proposal).
create policy "reviewers_insert" on public.reviews for insert
using (
  public.is_reviewer()
  and status not in ('accepted', 'rejected') -- correlated subquery or check? Need to check proposal status.
  and auth.uid() = reviewer_id -- default is auth.uid(), explicit check
  and not exists (
    select 1 from public.proposals p where p.id = proposal_id and p.speaker_id = auth.uid()
  )
);

-- R3: Reviewers can edit their own reviews while proposal is undecided.
-- Condition: reviewer_id (in row) == auth.uid() AND proposal is undecided.
create policy "reviewers_update_own_undecided" on public.reviews for update
using (
  reviewer_id = auth.uid()
  and not exists (
    select 1 from public.proposals p where p.id = proposal_id and p.status in ('accepted', 'rejected')
  )
);

-- R4: Reviewers see only their own reviews.
create policy "reviewers_see_own" on public.reviews for select
using (reviewer_id = auth.uid());

-- R4: Speakers can see reviews of their own proposals only after decision.
-- Condition: speaker_id (from proposal) == auth.uid() AND proposal status is decision made.
-- How to correlate? We need to join or use exists.
create policy "speakers_see_reviews_after_decision" on public.reviews for select
using (
  exists (
    select 1 from public.proposals p 
    where p.id = proposal_id 
    and p.speaker_id = auth.uid()
    and p.status not in ('submitted') -- Decision made means not submitted
  )
);

-- R6: Anonymous users cannot see or change anything.
revoke all on public.reviews from anon;
revoke all on public.reviews on all tables in schema public from anon;

-- Allow service_role full access
grant all on public.reviews to service_role;

-- ============================================================================
-- reviewers table: Allow users to see if they are reviewers (R5)
-- ============================================================================
-- Create a view or use a select policy? R5 says "users can see whether they themselves are a reviewer".
-- Usually this is done via a view or a specific policy on the table if needed.
-- Since the task asks to modify schema/rules, let's add a policy to allow self-check or a view.
-- Let's create a view for checking reviewer status as per R5 implication of "see whether".
-- Or simply allow select on reviewers table? R5 says "Nobody can change reviewers through the app".
-- It doesn't explicitly say reviewers can see the list, just "see whether they themselves are a reviewer".
-- Best practice: No direct access to the reviewers table rows by normal users to prevent enumeration attacks, 
-- but allow a specific check via a view or function if needed. 
-- However, the simplest interpretation of "see whether they themselves are a reviewer" is:
-- SELECT EXISTS(SELECT 1 FROM reviewers WHERE user_id = auth.uid()).
-- We can allow this specific query or create a view.
-- Let's create a view for clarity and security.

create view public.user_is_reviewer_view as
select 
  auth.uid() as user_id,
  exists (select 1 from public.reviewers where user_id = auth.uid()) as is_reviewer;

-- Enable RLS on the view and allow full access to authenticated users for this specific view
alter view public.user_is_reviewer_view enable row level security;
create policy "allow_check_reviewer_status" on public.user_is_reviewer_view for select
using (true);
grant select on public.user_is_reviewer_view to authenticated;

-- Ensure anon cannot access the view
revoke all on public.user_is_reviewer_view from anon;
revoke all on public.user_is_reviewer_view on all tables in schema public from anon;

-- ============================================================================
-- Final cleanup: Ensure strict isolation
-- ============================================================================
-- Revoke all permissions from anon on all tables to be absolutely sure (R6)
revoke all on public.reviewers from anon;
revoke all on public.proposals from anon;
revoke all on public.reviews from anon;

-- Ensure service_role has all needed (already granted above, but explicit re-grant ensures no accidental drop)
grant all on public.reviewers to service_role;
grant all on public.proposals to service_role;
grant all on public.reviews to service_role;
grant all on public.user_is_reviewer_view to service_role;
